// The api-bridge command list has a single source of truth: `src/command_list.rs`
// (the `bridge_commands!` invocation). Build scripts cannot import the crate, so we
// parse that same file here with the shared parser. This keeps the Tauri plugin
// permission autogeneration (`permissions/autogenerated/`) in lockstep with the
// runtime invoke handler; the tests in `command_registry.rs` assert it.
//
// Besides the per-command `allow-*`/`deny-*` permissions that `tauri-plugin`
// generates, each `module <id> { ... }` section gets one permission set,
// `module-<id>`, in `permissions/autogenerated/modules/<id>.toml`.
// `permissions/default.toml` grants modules through these sets.

use std::collections::BTreeSet;
use std::fs;
use std::path::Path;

include!("src/command_list_parser.rs");

const MODULE_SETS_DIR: &str = "permissions/autogenerated/modules";

fn main() {
    println!("cargo:rerun-if-changed=src/command_list.rs");
    println!("cargo:rerun-if-changed=src/command_list_parser.rs");

    let source = include_str!("src/command_list.rs");
    let sections = parse_command_sections(source)
        .unwrap_or_else(|err| panic!("malformed src/command_list.rs: {err}"));
    let commands: Vec<String> = sections
        .iter()
        .flat_map(|section| section.commands.iter().cloned())
        .collect();
    assert!(
        !commands.is_empty(),
        "no commands parsed from src/command_list.rs"
    );

    // Must exist before `tauri_plugin::Builder` globs `permissions/**`.
    write_module_permission_sets(&sections);

    // `tauri_plugin::Builder::new` wants `&'static [&'static str]`. The build
    // script runs once and exits, so leaking the parsed names is fine.
    let command_refs: Vec<&'static str> = commands
        .into_iter()
        .map(|name| &*Box::leak(name.into_boxed_str()))
        .collect();
    let command_refs: &'static [&'static str] = Box::leak(command_refs.into_boxed_slice());

    tauri_plugin::Builder::new(command_refs).build();
}

/// Write one `module-<id>` permission set per module section and remove sets
/// for modules that no longer exist. Files are only rewritten when their
/// contents change, so `rerun-if-changed=permissions` does not loop.
fn write_module_permission_sets(sections: &[CommandSection]) {
    let dir = Path::new(MODULE_SETS_DIR);
    fs::create_dir_all(dir).expect("create permissions/autogenerated/modules");

    let mut expected = BTreeSet::new();
    for section in sections {
        let Some(module) = &section.module else {
            continue;
        };
        let file_name = format!("{module}.toml");
        let path = dir.join(&file_name);
        let contents = module_permission_set_toml(module, &section.commands);
        if fs::read_to_string(&path).ok().as_deref() != Some(contents.as_str()) {
            fs::write(&path, contents).unwrap_or_else(|err| {
                panic!("write {}: {err}", path.display());
            });
        }
        expected.insert(file_name);
    }

    for entry in fs::read_dir(dir).expect("read permissions/autogenerated/modules") {
        let path = entry.expect("module permission entry").path();
        let name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default()
            .to_string();
        if name.ends_with(".toml") && !expected.contains(&name) {
            fs::remove_file(&path).unwrap_or_else(|err| {
                panic!("remove stale {}: {err}", path.display());
            });
        }
    }
}
